      out.write("													track.className = 'spot-marquee-track';\n");
      out.write("\n");
      out.write("													const a = document.createElement('span');\n");
      out.write("													a.className = 'spot-marquee-item';\n");
      out.write("													a.textContent = txt;\n");
      out.write("\n");
      out.write("													const b = document.createElement('span');\n");
      out.write("													b.className = 'spot-marquee-item';\n");
      out.write("													b.textContent = txt;\n");
      out.write("\n");
      out.write("													track.appendChild(a);\n");
      out.write("													track.appendChild(b);\n");
      out.write("\n");
      out.write("													const dist = a.getBoundingClientRect().width + 22;\n");
      out.write("													const speed = 50;\n");
      out.write("													const dur = Math.max(6, dist / speed);\n");
      out.write("\n");
      out.write("													track.style.setProperty('--spotMarqueeDist', dist + 'px');\n");
