      out.write("\n");
      out.write("											initSpotMarquee(container);\n");
      out.write("										}\n");
      out.write("\n");
      out.write("										function sideScroll(elementId, direction) {\n");
      out.write("											const container = document.getElementById(elementId);\n");
      out.write("											const card = container.querySelector('.card-item');\n");
      out.write("											if (!card) return;\n");
      out.write("											const scrollAmount = card.clientWidth + 20;\n");
      out.write("											if (direction === 'left') container.scrollLeft -= scrollAmount;\n");
      out.write("											else container.scrollLeft += scrollAmount;\n");
      out.write("										}\n");
      out.write("\n");
      out.write("										document.addEventListener(\"DOMContentLoaded\", function () {\n");
      out.write("											const savedCityId = sessionStorage.getItem(\"lastCityId\") || \"4\";\n");
      out.write("											const buttons = document.querySelectorAll('.city-btn');\n");
      out.write("											let targetBtn = null;\n");
      out.write("\n");
      out.write("											buttons.forEach(btn => {\n");
      out.write("												if (btn.getAttribute('onclick').includes(savedCityId)) {\n");
      out.write("													targetBtn = btn;\n");
      out.write("												}\n");
      out.write("											});\n");
      out.write("\n");
      out.write("											if (targetBtn) {\n");
      out.write("												loadCity(savedCityId, targetBtn);\n");
      out.write("											} else if (buttons.length > 0) {\n");
      out.write("												loadCity(\"4\", buttons[0]);\n");
      out.write("											}\n");
      out.write("										});\n");
      out.write("\n");
      out.write("										function toggleWish(event, sIdx, btn) {\n");
      out.write("											event.preventDefault();\n");
      out.write("											event.stopPropagation();\n");
      out.write("											fetch('/api/wish/toggle', {\n");
      out.write("												method: 'POST',\n");
      out.write("												headers: {\n");
      out.write("													'Content-Type': 'application/json'\n");
      out.write("												},\n");
      out.write("												body: JSON.stringify({sIdx: sIdx})\n");
      out.write("											})\n");
      out.write("												.then(response => {\n");
      out.write("													if (response.status === 401) {\n");
      out.write("														if (window.LoginRequiredPrompt) {window.LoginRequiredPrompt.open();} else {alert('로그인이 필요한 서비스입니다.');}\n");
      out.write("														return;\n");
      out.write("													}\n");
      out.write("													return response.json();\n");
      out.write("												})\n");
      out.write("												.then(data => {\n");
      out.write("													if (data && data.success) {\n");
      out.write("														btn.innerText = data.isHearted ? '❤️' : '🤍';\n");
      out.write("														if (data.isHearted) {\n");
      out.write("															btn.classList.add('active');\n");
      out.write("														} else {\n");
      out.write("															btn.classList.remove('active');\n");
      out.write("														}\n");
      out.write("													}\n");
      out.write("												})\n");
      out.write("												.catch(error => {\n");
      out.write("													console.error('Error:', error);\n");
      out.write("													alert('처리 중 오류가 발생했습니다.');\n");
      out.write("												});\n");
      out.write("										}\n");
      out.write("									</script>\n");
      out.write("			</div>\n");
      out.write("			");
